export interface AudioPluginOptions {
    /** Global master volume level (0.0 to 1.0). Default: 1.0 */
    masterVolume?: number;
    /** Default background music volume (0.0 to 1.0). Default: 0.5 */
    bgmVolume?: number;
    /** Default sound effect volume (0.0 to 1.0). Default: 1.0 */
    sfxVolume?: number;
    /** Default voiceover narration volume (0.0 to 1.0). Default: 1.0 */
    voiceoverVolume?: number;
    /** Sample rate for AudioContext (e.g. 48000). Default: hardware default */
    sampleRate?: number;
    /** Whether to auto-unlock AudioContext upon first user interaction. Default: true */
    autoUnlock?: boolean;
    /** Whether to auto-wire audio stream into LiveRecorder. Default: true */
    autoAttachRecorder?: boolean;
    /** Whether to pause audio when browser tab is hidden and resync when visible. Default: true */
    autoPauseOnHidden?: boolean;
    /** Whether to automatically attach AudioListenerComponent to scene.camera. Default: true */
    autoAttachListener?: boolean;
    /** Audio URLs or asset paths to preload into cache during initialization. */
    preload?: string[];
}

export interface BGMOptions {
    /** Volume multiplier (0.0 to 1.0). Default: 1.0 */
    volume?: number;
    /** Whether to loop playback indefinitely. Default: true */
    loop?: boolean;
    /** Fade-in duration in milliseconds. Default: 0 */
    fadeInMs?: number;
    /** Playback rate / pitch multiplier. Default: 1.0 */
    pitch?: number;
}

export interface SoundEffectOptions {
    /** URL or local asset path to the audio file. */
    src: string;
    /** Playback volume (0.0 to 1.0). Default: 1.0 */
    volume?: number;
    /** Pitch / playback rate multiplier. Default: 1.0 */
    pitch?: number;
