}

export interface VoiceoverOptions {
    /** Speech playback volume (0.0 to 1.0). Default: 1.0 */
    volume?: number;
    /** Background music volume multiplier during speech. 0.25 = 75% ducking. Default: 0.25 */
    duckingRatio?: number;
    /** Fade duration for volume ducking in milliseconds. Default: 300ms */
    fadeDurationMs?: number;
    /** Additional padding in milliseconds after speech finishes before resolving. Default: 0 */
    padEndMs?: number;
}

export interface SpatialAudioOptions {
    /** Audio URL or asset path. */
    src: string;
    /** Whether to loop playback. Default: true */
    loop?: boolean;
    /** Volume multiplier (0.0 to 1.0). Default: 1.0 */
    volume?: number;
    /** Distance within which volume is 100%. Default: 1 */
    refDistance?: number;
    /** Maximum distance after which sound no longer attenuates. Default: 10000 */
    maxDistance?: number;
    /** Rolloff factor describing how quickly sound fades with distance. Default: 1 */
    rolloffFactor?: number;
    /** Distance attenuation model ('inverse' | 'linear' | 'exponential'). Default: 'inverse' */
    distanceModel?: DistanceModelType;
    /** Panning model ('HRTF' for 3D binaural | 'equalpower'). Default: 'HRTF' */
    panningModel?: PanningModelType;
    /** Autoplay upon scene initialization. Default: true */
    autoplay?: boolean;
}

import { Scene, Circle, createAnim, FadeOut, Color, Rate, AudioPlugin } from 'retiam';

export class SoundDemoScene extends Scene {
    public async run() {
        // 1. Activate the audio plugin
        this.use(new AudioPlugin({ masterVolume: 0.85 }));

        // 2. Play background music with fade-in
        await this.audio.playBGM('assets/audio/synthwave.mp3', {
            volume: 0.35,
            loop: true,
            fadeInMs: 2000
        });

        const circle = new Circle(4);
        circle.paint.fill = new Color(0.1, 0.6, 1.0, 0.5);

        // 3. Play animation with attached SFX
        await this.play(createAnim(circle), {
            duration: 1500,
            rate_func: Rate.easeOutBack(),
            sound: 'assets/audio/whoosh.mp3' // Automatically triggered via anim:sound event
        });

        await this.wait(500);

        // 4. Standalone SFX trigger
        this.audio.playSFX('assets/audio/pop.mp3', { pitch: 1.25 });

        await this.play(new FadeOut(circle), { duration: 800 });
    }
}

import { Scene, Text, Write, AudioPlugin } from 'retiam';

export class LectureScene extends Scene {
    public async run() {
        this.use(new AudioPlugin());
        this.audio.playBGM('assets/audio/ambient_study.mp3', { volume: 0.4 });

        const equation = new Text("E = mc^2");

        // The voiceover automatically:
        // 1. Ducks background music down to 20% (80% reduction) over 300ms
        // 2. Plays speech on the voiceover bus
        // 3. Resolves when speech finishes and smoothly restores BGM volume
        await Promise.all([
            this.play(new Write(equation), { duration: 2500 }),
            this.audio.playVoiceover('assets/audio/explanation_einstein.mp3', {
                duckingRatio: 0.20,
                fadeDurationMs: 400
            })
        ]);
    }
}

import { Scene, AudioPlugin, Rect, Color } from 'retiam';

export class VisualizerScene extends Scene {
    public async run() {
        this.composer.ALWAYS_UPDATE = true;
        this.use(new AudioPlugin());

        await this.audio.playBGM('assets/audio/electronic.mp3');

        // 1. Create analyzer (64 frequency bins)
        const analyzer = this.audio.createAnalyzer({ fftSize: 128 });

        // 2. Stream FFT data to a 1D GPUTexture for custom shaders
        const spectrumTexture = analyzer.createSpectrumTexture(this.device);

        // 3. Visualizer Bars (16 bars)
        const bars: Rect[] = [];
        for (let i = 0; i < 16; i++) {
            const bar = new Rect(1.2, 1.0);
            bar.transform.position.set([-12 + i * 1.6, -5, 0]);
            bar.paint.fill = new Color(0.2 + (i / 16) * 0.7, 0.4, 0.9, 0.85);
            this.add(bar);
            bars.push(bar);
        }

        // 4. Update loop: stream texture to GPU and animate bar scales
        this.always(() => {
            // Upload to GPU texture (sampled by WGSL shaders via textureSample)
            analyzer.updateSpectrumTexture(this.device);

            // Read macro bands for CPU animations
            const data = analyzer.getFrequencyData();
            for (let i = 0; i < 16; i++) {
                const height = Math.max(0.2, (data[i * 2] / 255) * 8.0);
                bars[i].transform.setScale(1.0, height, 1.0);
            }

            // Or use the one-line normalized bands getter:
            const { bass } = this.audio.bands;
            // e.g. pulse a light or scale an object: pulseCircle.setScale([1 + bass, 1 + bass, 1]);
        });
    }
}

import {
    Scene,
    Sphere,
    OrbitCameraController,
    AudioPlugin,
    SpatialAudioComponent
} from 'retiam';

export class SpatialScene extends Scene {
    public async run() {
        // AudioListenerComponent is automatically attached to this.camera by default!
        this.use(new AudioPlugin({ autoAttachListener: true }));

        this.camera.position.set([0, 5, 30]);
        new OrbitCameraController(this, this.camera);

        // Moving 3D sound source
        const drone = new Sphere(1.5);
        drone.transform.position.set([-25, 0, 0]); // Start on the left

        drone.addComponent(new SpatialAudioComponent({
            src: 'assets/audio/drone_engine.mp3',
            loop: true,
            refDistance: 4,
            maxDistance: 60,
            rolloffFactor: 1.5,
            panningModel: 'HRTF'
        }));

        this.add(drone);

        // Move drone across the camera: sound naturally shifts from left ear to right ear!
        await this.play(
            drone.animate.position.set([25, 0, 0]),
            { duration: 5000 }
        );
    }
}

import { LiveRecorder } from 'retiam';

// Inside your scene run() or recording trigger:
const recorder = new LiveRecorder(this.canvas, 'mp4');

// Connect audio from the active plugin directly with one call:
if (this.audio) {
    this.audio.attachRecorder(recorder);
}

await recorder.start();

// ... execute animations ...

await recorder.stop(); // Automatically muxes video and stereo AAC/Opus audio into the file!

// Pattern 1: Raw PCM amplitude numbers [-1.0 to 1.0] (Fundamental Primitive)
const rawBuffer = this.audio.createBuffer([0, 0.5, 1.0, 0.5, 0, -0.5, -1.0, -0.5]);
this.audio.timeline.addClip(rawBuffer, this.time, this.audio.sfxGain, { pitch: 1.5 });

// Pattern 2: Additive Harmonic Frequencies & Chords (with exponential decay)
const chordBuffer = this.audio.createTone([
    { freq: 440.00, amp: 1.0 }, // A4
    { freq: 554.37, amp: 0.7 }, // C#5
    { freq: 659.25, amp: 0.5 }  // E5
], 1.5, 2.0); // 1.5s duration, 2.0 decay rate
this.audio.timeline.addClip(chordBuffer, this.time, this.audio.sfxGain);

// Pattern 3: Mathematical Generator Function f(t) -> amplitude
const laserChirp = this.audio.createWave((t) => {
    const freq = 880 * Math.exp(-8 * t) + 150;
    const env = Math.exp(-6 * t);
    return Math.sin(2 * Math.PI * freq * t) * env;
}, 0.5);
this.audio.timeline.addClip(laserChirp, this.time, this.audio.sfxGain);

// 1. Allocate a short 0.25-second buffer (e.g. 12,000 samples at 48kHz)
const sampleRate = this.audio.context.sampleRate;
const bufferLength = Math.floor(sampleRate * 0.25);
const liveBuffer = this.audio.createBuffer(new Float32Array(bufferLength), sampleRate);
const channelData = liveBuffer.getChannelData(0);

// 2. Play the buffer in a loop
this.audio.timeline.addClip(liveBuffer, 0, this.audio.bgmGain, {
    volume: 0.35,
    loop: true
});

// 3. Continuously rewrite samples in the frame loop (morphing frequency & harmonics)
let phase = 0;
this.always((t: number) => {
    const timeSec = t * 0.001;
    const currentFreq = 220 + Math.sin(timeSec * 2.0) * 100;
    const phaseIncrement = (2 * Math.PI * currentFreq) / sampleRate;

    for (let i = 0; i < bufferLength; i++) {
        channelData[i] = Math.sin(phase) * 0.4;
        phase += phaseIncrement;
    }
    phase = phase % (2 * Math.PI);
});
